'use client'

import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react'
import { createPortal } from 'react-dom'
import { AnimatePresence, motion, useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'
import { springs } from '@/lib/motion-tokens'
import { useProximityHighlight, ProximityHighlight } from '@/lib/hooks/use-proximity-highlight'

export interface ContextMenuItem {
  label: string
  icon?: ReactNode
  shortcut?: string
  onSelect?: () => void
  destructive?: boolean
  disabled?: boolean
  separatorAfter?: boolean
}

interface ContextMenuContextValue {
  open: boolean
  setOpen: (next: boolean) => void
  items: ContextMenuItem[]
  onOpenChange?: (open: boolean) => void
}

const ContextMenuContext = createContext<ContextMenuContextValue | null>(null)

function useContextMenuCtx(componentName: string) {
  const ctx = useContext(ContextMenuContext)
  if (!ctx) throw new Error(`${componentName} must be used within ContextMenu`)
  return ctx
}

export interface ContextMenuProps {
  children: ReactNode
  items: ContextMenuItem[]
  disabled?: boolean
  onOpenChange?: (open: boolean) => void
  className?: string
  menuClassName?: string
}

export const ContextMenu = forwardRef<HTMLDivElement, ContextMenuProps>(
  ({ children, items, disabled = false, onOpenChange, className, menuClassName }, ref) => {
    const [open, setOpen] = useState(false)
    const [position, setPosition] = useState({ x: 0, y: 0 })
    const triggerRef = useRef<HTMLDivElement>(null)
    const contentRef = useRef<HTMLDivElement>(null)
    const longPressTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
    const longPressMovedRef = useRef(false)
    const previousFocusRef = useRef<HTMLElement | null>(null)

    const setOpenState = useCallback(
      (next: boolean) => {
        setOpen(next)
        onOpenChange?.(next)
      },
      [onOpenChange],
    )

    const handleContextMenu = useCallback(
      (e: React.MouseEvent) => {
        if (disabled) return
        e.preventDefault()
        previousFocusRef.current = document.activeElement as HTMLElement | null
        setPosition({ x: e.clientX, y: e.clientY })
        setOpenState(true)
      },
      [disabled, setOpenState],
    )

    const handleTouchStart = useCallback(
      (e: React.TouchEvent) => {
        if (disabled) return
        longPressMovedRef.current = false
        const touch = e.touches[0]
        longPressTimerRef.current = setTimeout(() => {
          if (!longPressMovedRef.current) {
            previousFocusRef.current = document.activeElement as HTMLElement | null
            setPosition({ x: touch.clientX, y: touch.clientY })
            setOpenState(true)
          }
        }, 500)
      },
      [disabled, setOpenState],
    )

    const handleTouchMove = useCallback(() => {
      longPressMovedRef.current = true
      if (longPressTimerRef.current) {
        clearTimeout(longPressTimerRef.current)
        longPressTimerRef.current = null
      }
    }, [])

    const handleTouchEnd = useCallback(() => {
      if (longPressTimerRef.current) {
        clearTimeout(longPressTimerRef.current)
        longPressTimerRef.current = null
      }
    }, [])

    const handleKeyDown = useCallback(
      (e: React.KeyboardEvent) => {
        if (disabled) return
        if (e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10')) {
          e.preventDefault()
          previousFocusRef.current = document.activeElement as HTMLElement | null
          const rect = triggerRef.current?.getBoundingClientRect()
          if (rect) {
            setPosition({ x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 })
          }
          setOpenState(true)
        }
      },
      [disabled, setOpenState],
    )

    useEffect(() => {
      if (!open) return
      const handlePointerDown = (e: PointerEvent) => {
        if (contentRef.current && !contentRef.current.contains(e.target as Node)) {
          setOpenState(false)
        }
      }
      const handleEscape = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
          e.preventDefault()
          setOpenState(false)
          previousFocusRef.current?.focus()
        }
      }
      document.addEventListener('pointerdown', handlePointerDown)
      document.addEventListener('keydown', handleEscape)
      return () => {
        document.removeEventListener('pointerdown', handlePointerDown)
        document.removeEventListener('keydown', handleEscape)
      }
    }, [open, setOpenState])

    useEffect(() => {
      return () => {
        if (longPressTimerRef.current) {
          clearTimeout(longPressTimerRef.current)
        }
      }
    }, [])

    const ctx = useMemo<ContextMenuContextValue>(
      () => ({ open, setOpen: setOpenState, items, onOpenChange }),
      [open, setOpenState, items, onOpenChange],
    )

    return (
      <ContextMenuContext.Provider value={ctx}>
        <div
          ref={(node) => {
            ;(triggerRef as React.MutableRefObject<HTMLDivElement | null>).current = node
            if (typeof ref === 'function') ref(node)
            else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node
          }}
          onContextMenu={handleContextMenu}
          onTouchStart={handleTouchStart}
          onTouchMove={handleTouchMove}
          onTouchEnd={handleTouchEnd}
          onKeyDown={handleKeyDown}
          className={cn('inline-block', className)}
        >
          {children}
        </div>
        <AnimatePresence>
          {open && (
            <ContextMenuPanel ref={contentRef} position={position} className={menuClassName} />
          )}
        </AnimatePresence>
      </ContextMenuContext.Provider>
    )
  },
)
ContextMenu.displayName = 'ContextMenu'

interface ContextMenuPanelProps {
  position: { x: number; y: number }
  className?: string
}

const ContextMenuPanel = forwardRef<HTMLDivElement, ContextMenuPanelProps>(
  ({ position, className }, ref) => {
    const { items, setOpen } = useContextMenuCtx('ContextMenuPanel')
    const panelRef = useRef<HTMLDivElement | null>(null)
    const reduceMotion = useReducedMotion()
    const menuId = useId()

    const { registerItem, handlers, highlightX, highlightSize, highlightOpacity, axis } =
      useProximityHighlight(panelRef, { axis: 'y' })

    const indexRef = useRef(0)
    const nextIndex = useCallback(() => {
      const idx = indexRef.current
      indexRef.current += 1
      return idx
    }, [])

    const [adjustedPos, setAdjustedPos] = useState(position)
    const [transformOrigin, setTransformOrigin] = useState('top left')
    useEffect(() => {
      const panel = panelRef.current
      if (!panel) return
      const rect = panel.getBoundingClientRect()
      const vw = window.innerWidth
      const vh = window.innerHeight
      const margin = 8
      const vCenterX = vw / 2
      const vCenterY = vh / 2

      // Grow away from the cursor's quadrant to stay on screen, anchoring the
      // chosen origin corner exactly at the cursor rather than clamping.
      const horizontal = position.x < vCenterX ? 'left' : 'right'
      const vertical = position.y < vCenterY ? 'top' : 'bottom'

      let x = horizontal === 'left' ? position.x : position.x - rect.width
      let y = vertical === 'top' ? position.y : position.y - rect.height

      if (x + rect.width > vw - margin) x = vw - rect.width - margin
      if (y + rect.height > vh - margin) y = vh - rect.height - margin
      if (x < margin) x = margin
      if (y < margin) y = margin

      setAdjustedPos({ x, y })
      setTransformOrigin(`${vertical} ${horizontal}`)
    }, [position])

    useEffect(() => {
      const panel = panelRef.current
      if (!panel) return

      const firstItem = panel.querySelector<HTMLElement>('[role="menuitem"]:not([data-disabled])')
      firstItem?.focus()

      const handleKeyDown = (e: KeyboardEvent) => {
        if (!panel.contains(document.activeElement)) return
        const menuItems = panel.querySelectorAll<HTMLElement>(
          '[role="menuitem"]:not([data-disabled])',
        )
        if (!menuItems.length) return
        const count = menuItems.length
        const currentIdx = Array.from(menuItems).indexOf(document.activeElement as HTMLElement)

        if (e.key === 'ArrowDown') {
          e.preventDefault()
          const next = currentIdx < 0 ? 0 : (currentIdx + 1) % count
          menuItems[next]?.focus()
        } else if (e.key === 'ArrowUp') {
          e.preventDefault()
          const next = currentIdx < 0 ? count - 1 : (currentIdx - 1 + count) % count
          menuItems[next]?.focus()
        } else if (e.key === 'Home') {
          e.preventDefault()
          menuItems[0]?.focus()
        } else if (e.key === 'End') {
          e.preventDefault()
          menuItems[count - 1]?.focus()
        } else if (e.key === 'Tab') {
          setOpen(false)
        } else if (e.key.length === 1 && !e.altKey && !e.ctrlKey && !e.metaKey && e.key.trim()) {
          const query = e.key.toLowerCase()
          const match = Array.from(menuItems).findIndex((el) => {
            const text = (el.getAttribute('data-text-value') ?? el.textContent ?? '').toLowerCase()
            return text.startsWith(query)
          })
          if (match >= 0) {
            e.preventDefault()
            menuItems[match]?.focus()
          }
        }
      }
      document.addEventListener('keydown', handleKeyDown)
      return () => document.removeEventListener('keydown', handleKeyDown)
    }, [setOpen])

    const setRefs = useCallback(
      (el: HTMLDivElement | null) => {
        ;(panelRef as React.MutableRefObject<HTMLDivElement | null>).current = el
        if (typeof ref === 'function') ref(el)
        else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = el
      },
      [ref],
    )

    const panelContent = (
      <motion.div
        ref={setRefs}
        id={menuId}
        role="menu"
        data-context-menu-content
        className={cn(
          'fixed z-300 min-w-48 max-w-[calc(100vw-1.5rem)] overflow-hidden rounded-md squircle-corners border border-(--color-border) bg-(--color-bg) p-1.5 outline-none',
          'shadow-lg',
          className,
        )}
        style={{
          left: adjustedPos.x,
          top: adjustedPos.y,
          transformOrigin,
        }}
        initial={reduceMotion ? { opacity: 1 } : { opacity: 0, scale: 0.95 }}
        animate={reduceMotion ? { opacity: 1 } : { opacity: 1, scale: 1 }}
        exit={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.95 }}
        transition={
          reduceMotion ? { duration: 0 } : { ...springs.settle, opacity: { duration: 0.12 } }
        }
        tabIndex={-1}
        {...handlers}
      >
        <ProximityHighlight
          highlightX={highlightX}
          highlightSize={highlightSize}
          highlightOpacity={highlightOpacity}
          axis={axis}
          className="mx-1.5 rounded-md squircle-corners bg-(--color-surface-2)"
        />
        {items.map((item, i) => {
          if (item.separatorAfter) {
            return (
              <div key={`item-${i}`}>
                <ContextMenuItemComponent
                  item={item}
                  nextIndex={nextIndex}
                  registerItem={registerItem}
                />
                <div
                  role="separator"
                  aria-hidden="true"
                  className="my-1 h-px bg-(--color-border)"
                />
              </div>
            )
          }
          return (
            <ContextMenuItemComponent
              key={`item-${i}`}
              item={item}
              nextIndex={nextIndex}
              registerItem={registerItem}
            />
          )
        })}
      </motion.div>
    )

    return createPortal(panelContent, document.body)
  },
)
ContextMenuPanel.displayName = 'ContextMenuPanel'

function ContextMenuItemComponent({
  item,
  nextIndex,
  registerItem,
}: {
  item: ContextMenuItem
  nextIndex: () => number
  registerItem: (index: number, el: HTMLElement | null) => void
}) {
  const { setOpen } = useContextMenuCtx('ContextMenuItem')
  const itemRef = useRef<HTMLButtonElement | null>(null)
  const [idx] = useState(() => nextIndex())

  useEffect(() => {
    const el = itemRef.current
    if (idx < 0 || !el) return
    registerItem(idx, el)
    return () => registerItem(idx, null)
  }, [idx, registerItem])

  return (
    <button
      ref={itemRef}
      type="button"
      role="menuitem"
      data-text-value={item.label}
      data-disabled={item.disabled ? '' : undefined}
      tabIndex={-1}
      disabled={item.disabled}
      className={cn(
        'relative flex min-h-11 w-full cursor-default select-none items-center gap-3 rounded-md squircle-corners px-3 py-2.5 text-left text-sm outline-none transition-colors duration-(--motion-dur-fast) motion-reduce:transition-none',
        'data-disabled:pointer-events-none data-disabled:opacity-50',
        item.destructive
          ? 'text-(--color-error) focus-visible:text-(--color-error)'
          : 'text-(--color-fg)',
      )}
      onClick={() => {
        if (!item.disabled) {
          item.onSelect?.()
          setOpen(false)
        }
      }}
    >
      {item.icon && (
        <span className="relative z-10 shrink-0 [&_svg]:size-4" aria-hidden="true">
          {item.icon}
        </span>
      )}
      <span className="relative z-10 flex min-w-0 flex-1 items-center truncate">{item.label}</span>
      {item.shortcut && (
        <kbd
          className="relative z-10 shrink-0 rounded-md border border-(--color-border) bg-(--color-surface) px-1.5 py-0.5 text-[10px] font-normal text-(--color-subtle)"
          aria-hidden="true"
        >
          {item.shortcut}
        </kbd>
      )}
    </button>
  )
}

export function ContextMenuPreview() {
  return (
    <div
      className="flex h-full w-full items-center justify-center p-6"
      style={{ backgroundColor: 'var(--color-surface)' }}
    >
      <ContextMenu
        items={[
          { label: 'Copy', shortcut: '⌘C' },
          { label: 'Rename', separatorAfter: true },
          { label: 'Delete', destructive: true },
        ]}
      >
        <div className="flex h-32 w-48 items-center justify-center rounded-md squircle-corners border border-(--color-border) bg-(--color-bg) text-sm text-(--color-muted)">
          Right-click me
        </div>
      </ContextMenu>
    </div>
  )
}

'use client'

import { useRef, useState, useCallback, useEffect, type RefObject } from 'react'
import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  type MotionValue,
  type MotionStyle,
} from 'motion/react'
import { springs } from '@/lib/motion-tokens'

export interface ItemRect {
  top: number
  height: number
  left: number
  width: number
}

interface UseProximityHighlightOptions {
  axis?: 'x' | 'y'
  spring?: { stiffness: number; damping: number; mass: number }
}

interface UseProximityHighlightReturn {
  activeIndex: number | null
  setActiveIndex: (index: number | null) => void
  itemRects: ItemRect[]
  sessionRef: RefObject<number>
  handlers: {
    onMouseMove: (e: React.MouseEvent) => void
    onMouseEnter: () => void
    onMouseLeave: () => void
  }
  registerItem: (index: number, element: HTMLElement | null) => void
  measureItems: () => void
  highlightX: ReturnType<typeof useSpring>
  highlightSize: MotionValue<number>
  highlightOpacity: ReturnType<typeof useSpring>
  axis: 'x' | 'y'
}

export function useProximityHighlight<T extends HTMLElement>(
  containerRef: RefObject<T | null>,
  options: UseProximityHighlightOptions = {},
): UseProximityHighlightReturn {
  const { axis = 'y', spring: springConfig } = options
  const reduceMotion = useReducedMotion()

  const itemsRef = useRef(new Map<number, HTMLElement>())
  const [activeIndex, setActiveIndexRaw] = useState<number | null>(null)
  const activeIndexRef = useRef<number | null>(null)
  const [itemRects, setItemRects] = useState<ItemRect[]>([])
  const itemRectsRef = useRef<ItemRect[]>([])
  const sessionRef = useRef(0)
  const rafIdRef = useRef<number | null>(null)
  const remeasureRafIdRef = useRef<number | null>(null)
  const updateHighlightRef = useRef<(index: number | null) => void>(() => {})

  const rawX = useMotionValue(0)
  const highlightSize = useMotionValue(0)
  const rawOpacity = useMotionValue(0)

  const springOpts = reduceMotion ? { duration: 0 } : (springConfig ?? springs.settle)

  const highlightX = useSpring(rawX, springOpts)
  const highlightOpacity = useSpring(rawOpacity, springOpts)

  const measureItems = useCallback(() => {
    const container = containerRef.current
    if (!container) return
    const rects: ItemRect[] = []
    itemsRef.current.forEach((element, index) => {
      rects[index] = {
        top: element.offsetTop,
        height: element.offsetHeight,
        left: element.offsetLeft,
        width: element.offsetWidth,
      }
    })
    itemRectsRef.current = rects
    setItemRects(rects)
  }, [containerRef])

  const registerItem = useCallback(
    (index: number, element: HTMLElement | null) => {
      if (element) {
        itemsRef.current.set(index, element)
      } else {
        itemsRef.current.delete(index)
      }
      if (remeasureRafIdRef.current !== null) {
        cancelAnimationFrame(remeasureRafIdRef.current)
      }
      remeasureRafIdRef.current = requestAnimationFrame(() => {
        remeasureRafIdRef.current = null
        measureItems()
      })
    },
    [measureItems],
  )

  const updateHighlight = useCallback(
    (index: number | null) => {
      if (index === null || !itemRectsRef.current[index]) {
        if (reduceMotion) {
          rawOpacity.jump(0)
        } else {
          rawOpacity.set(0)
        }
        return
      }
      const r = itemRectsRef.current[index]
      if (axis === 'y') {
        if (reduceMotion) {
          rawX.jump(r.top)
          highlightSize.jump(r.height)
          rawOpacity.jump(1)
        } else {
          rawX.set(r.top)
          highlightSize.jump(r.height)
          rawOpacity.set(1)
        }
      } else {
        if (reduceMotion) {
          rawX.jump(r.left)
          highlightSize.jump(r.width)
          rawOpacity.jump(1)
        } else {
          rawX.set(r.left)
          highlightSize.jump(r.width)
          rawOpacity.set(1)
        }
      }
    },
    [axis, reduceMotion, rawX, highlightSize, rawOpacity],
  )

  useEffect(() => {
    updateHighlightRef.current = updateHighlight
  })

  const setActiveIndex = useCallback((index: number | null) => {
    setActiveIndexRaw(index)
    updateHighlightRef.current(index)
  }, [])

  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      const mouseX = e.clientX
      const mouseY = e.clientY

      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current)
      }

      rafIdRef.current = requestAnimationFrame(() => {
        rafIdRef.current = null
        const container = containerRef.current
        if (!container) return

        const containerRect = container.getBoundingClientRect()
        const mousePos = axis === 'x' ? mouseX : mouseY

        let closestIndex: number | null = null
        let closestDistance = Infinity
        let containingIndex: number | null = null

        const rects = itemRectsRef.current
        const scrollOffset = axis === 'x' ? container.scrollLeft : container.scrollTop
        const borderOffset = axis === 'x' ? container.clientLeft : container.clientTop
        const containerEdge = axis === 'x' ? containerRect.left : containerRect.top

        const layoutSize = axis === 'x' ? container.offsetWidth : container.offsetHeight
        const visualSize = axis === 'x' ? containerRect.width : containerRect.height
        const scale = layoutSize > 0 ? visualSize / layoutSize : 1

        for (let index = 0; index < rects.length; index++) {
          const r = rects[index]
          if (!r) continue

          const contentPos = axis === 'x' ? r.left : r.top
          const itemStart = containerEdge + (borderOffset + contentPos - scrollOffset) * scale
          const itemSize = (axis === 'x' ? r.width : r.height) * scale
          const itemEnd = itemStart + itemSize

          if (mousePos >= itemStart && mousePos <= itemEnd) {
            containingIndex = index
          }

          const itemCenter = itemStart + itemSize / 2
          const distance = Math.abs(mousePos - itemCenter)

          if (distance < closestDistance) {
            closestDistance = distance
            closestIndex = index
          }
        }

        const next = containingIndex ?? closestIndex
        if (next !== activeIndexRef.current) {
          activeIndexRef.current = next
          setActiveIndex(next)
        }
      })
    },
    [axis, containerRef, setActiveIndex],
  )

  const handleMouseEnter = useCallback(() => {
    sessionRef.current += 1
  }, [])

  const handleMouseLeave = useCallback(() => {
    if (rafIdRef.current !== null) {
      cancelAnimationFrame(rafIdRef.current)
      rafIdRef.current = null
    }
    activeIndexRef.current = null
    setActiveIndex(null)
  }, [setActiveIndex])

  useEffect(() => {
    return () => {
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current)
      }
      if (remeasureRafIdRef.current !== null) {
        cancelAnimationFrame(remeasureRafIdRef.current)
      }
    }
  }, [])

  return {
    activeIndex,
    setActiveIndex,
    itemRects,
    sessionRef,
    handlers: {
      onMouseMove: handleMouseMove,
      onMouseEnter: handleMouseEnter,
      onMouseLeave: handleMouseLeave,
    },
    registerItem,
    measureItems,
    highlightX,
    highlightSize,
    highlightOpacity,
    axis,
  }
}

export interface ProximityHighlightProps {
  highlightX: ReturnType<typeof useSpring>
  highlightSize: MotionValue<number>
  highlightOpacity: ReturnType<typeof useSpring>
  axis: 'x' | 'y'
  className?: string
  style?: MotionStyle
}

export function ProximityHighlight({
  highlightX,
  highlightSize,
  highlightOpacity,
  axis,
  className,
  style,
}: ProximityHighlightProps) {
  return (
    <motion.div
      aria-hidden="true"
      className={className}
      style={{
        ...style,
        position: 'absolute',
        inset: 0,
        pointerEvents: 'none',
        ...(axis === 'y'
          ? { y: highlightX, height: highlightSize }
          : { x: highlightX, width: highlightSize }),
        opacity: highlightOpacity,
      }}
    />
  )
}

export function useRegisterProximityItem(
  registerItem: (index: number, element: HTMLElement | null) => void,
  index: number,
  ref: RefObject<HTMLElement | null>,
) {
  useEffect(() => {
    registerItem(index, ref.current)
    return () => registerItem(index, null)
  }, [index, registerItem, ref])
}

export const durations = {
  instant: '50ms',
  fast: '120ms',
  base: '200ms',
  slow: '320ms',
} as const

export const easings = {
  out: 'cubic-bezier(0.22, 1, 0.36, 1)',
  inOut: 'cubic-bezier(0.65, 0, 0.35, 1)',
} as const

export const springs = {
  fast: { type: 'spring', stiffness: 400, damping: 30, mass: 0.8 },
  press: { type: 'spring', stiffness: 700, damping: 32, mass: 1 },
  moderate: { type: 'spring', stiffness: 300, damping: 24, mass: 1 },
  settle: { type: 'spring', stiffness: 260, damping: 26, mass: 1 },
} as const
